<?php
declare(strict_types=1);

function qa180_demo(array $tenant):bool {return !empty($GLOBALS['demo_context'])&&(int)$GLOBALS['demo_context']['tenant_id']===(int)$tenant['id'];}
function qa180_print_enqueue(App $app,array $tenant,array $branch,array $user,string $point,string $key,string $text,bool $drawer=false,bool $copy=false):int {
    if(!$app->db->inTransaction())throw new LogicException('La impresión debe guardarse con su operación.');
    $points=r3_print_points($app,$tenant);if(!isset($points[$point]))throw new DomainException('El destino de impresión no está configurado.');
    $profile=printer_profile_148($branch,$point);$device=null;$register=qa180_native($app,$user,false,'print');
    if(!empty($profile['device_id']))$device=$app->one('SELECT id FROM fisitaap_r2_devices WHERE id=? AND tenant_id=? AND branch_id=? AND is_active=1',[$profile['device_id'],$tenant['id'],$branch['id']]);
    elseif($register)$device=['id'=>(int)$register['device_id']];
    else $device=$app->one('SELECT d.id FROM fisitaap_primary179 p JOIN fisitaap_r2_devices d ON d.id=p.device_id WHERE p.tenant_id=? AND d.branch_id=? AND d.is_active=1',[$tenant['id'],$branch['id']]);
    $demo=qa180_demo($tenant);if($demo)$device=null;
    $drawer=$drawer&&!$copy&&!$demo&&$point==='receipt'&&!empty($profile['drawer'])&&!empty($register['drawer_enabled']);
    $payload=['id'=>'tenant-'.$tenant['id'].'-'.$key,'document'=>$point,'width'=>$profile['width'],'printer'=>$profile,'text'=>$text,'demo'=>$demo,'copy'=>$copy,'drawer'=>$drawer];
    $hash=hash('sha256',json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$old=$app->one('SELECT id,payload_hash FROM fisitaap_print_jobs180 WHERE tenant_id=? AND operation_key=?',[$tenant['id'],$key]);
    if($old){if(!hash_equals($old['payload_hash'],$hash))throw new DomainException('La misma impresión ya tiene otro contenido. Usa Reimprimir copia.');return (int)$old['id'];}
    $app->exec('INSERT INTO fisitaap_print_jobs180(tenant_id,branch_id,device_id,user_id,operation_key,payload_hash,point,payload,status) VALUES(?,?,?,?,?,?,?,?,?)',[$tenant['id'],$branch['id'],$device['id']??null,$user['id'],$key,$hash,$point,json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$demo?'simulated':'queued']);return (int)$app->db->lastInsertId();
}
function qa180_print_commands(App $app,array $tenant,array $branch,array $user,int $ticketId,array $ids,string $key):void {
    $ticket=$app->one('SELECT * FROM pos_tickets WHERE id=? AND tenant_id=? AND branch_id=?',[$ticketId,$tenant['id'],$branch['id']]);if(!$ticket)throw new DomainException('Cuenta no disponible.');
    $groups=[];foreach($app->all('SELECT i.*,COALESCE(c.printer_target,"kitchen") target FROM pos_ticket_items i JOIN products p ON p.id=i.product_id LEFT JOIN categories c ON c.id=p.category_id WHERE i.ticket_id=? ORDER BY i.id',[$ticketId]) as $item)if(in_array((int)$item['id'],array_map('intval',$ids),true))$groups[$item['target']][]=$item;
    foreach($groups as $point=>$items){$lines=[$tenant['name'],$branch['name'],'COMANDA · '.(r3_print_points($app,$tenant)[$point]??$point),$ticket['ticket_number'],$ticket['display_label']??'',date('d/m/Y H:i',strtotime($ticket['created_at'])),'--------------------------------'];foreach($items as $item){$lines[]=$item['quantity'].' × '.$item['product_name'];foreach(json_decode((string)$item['options_json'],true)?:[] as $option)$lines[]='  '.$option['name'];if($item['notes'])$lines[]='  Nota: '.$item['notes'];}if($ticket['notes'])$lines[]='Cuenta: '.$ticket['notes'];qa180_print_enqueue($app,$tenant,$branch,$user,$point,$key.'-'.$point,implode("\n",array_filter($lines,fn($x)=>$x!==null&&$x!=='')),false);}
}
function qa180_print_sale(App $app,array $tenant,array $branch,array $user,int $saleId,bool $receipt=true):void {
    $sale=$app->one('SELECT * FROM sales WHERE id=? AND tenant_id=? AND branch_id=?',[$saleId,$tenant['id'],$branch['id']]);if(!$sale)throw new DomainException('Venta no disponible.');
    if($receipt){$lines=[$tenant['name'],$branch['name']];if(!empty($tenant['tax_id']))$lines[]='Identificación: '.$tenant['tax_id'];$lines[]='RECIBO · '.$sale['sale_number'];$lines[]=date('d/m/Y H:i',strtotime($sale['created_at']));$lines[]='Cliente: '.$sale['customer_name'];$lines[]='--------------------------------';foreach($app->all('SELECT * FROM sale_items WHERE sale_id=? ORDER BY id',[$saleId]) as $item){$lines[]=$item['quantity'].' × '.$item['product_name'].' '.money((float)$item['line_subtotal']+(float)$item['line_tax']);foreach(json_decode((string)$item['options_json'],true)?:[] as $option)$lines[]='  '.$option['name'];if($item['notes'])$lines[]='  Nota: '.$item['notes'];}$lines[]='--------------------------------';foreach(['subtotal'=>'Subtotal','tax_total'=>'Impuesto','service_total'=>'Servicio','discount_total'=>'Descuento','total'=>'TOTAL','change_due'=>'Vuelto'] as $field=>$label)$lines[]=$label.' '.money((float)$sale[$field]);$lines[]='Pago: '.$sale['payment_method'];$lines[]='Gracias por su compra.';
        $cash=(float)$app->one('SELECT COALESCE(SUM(amount),0) amount FROM pos_payments WHERE sale_id=? AND payment_method="Efectivo"',[$saleId])['amount'];qa180_print_enqueue($app,$tenant,$branch,$user,'receipt','sale-'.$saleId,implode("\n",$lines),$cash>0);
    }
    foreach(json_decode((string)$sale['kitchen_jobs_json'],true)?:[] as $job)qa180_print_commands($app,$tenant,$branch,$user,(int)$job['ticket_id'],$job['items'],'sale-'.$saleId.'-command-'.$job['ticket_id']);
}
function qa180_print_api(App $app,array $device,string $action,array $data):array {
    if($action==='print-claim'){
        $app->db->beginTransaction();try{
            $app->one('SELECT id FROM fisitaap_r2_devices WHERE id=? FOR UPDATE',[$device['id']]);
            $job=$app->one('SELECT * FROM fisitaap_print_jobs180 WHERE tenant_id=? AND branch_id=? AND device_id=? AND (status="queued" OR (status="claimed" AND lease_expires<NOW())) ORDER BY id LIMIT 1 FOR UPDATE',[$device['tenant_id'],$device['branch_id'],$device['id']]);
            if(!$job){$app->db->commit();return ['ok'=>true,'job'=>null];}
            $claim=bin2hex(random_bytes(16));$app->exec('UPDATE fisitaap_print_jobs180 SET status="claimed",claim_token=?,lease_expires=DATE_ADD(NOW(),INTERVAL 90 SECOND),attempts=attempts+1 WHERE id=?',[$claim,$job['id']]);$app->db->commit();return ['ok'=>true,'job'=>['id'=>(int)$job['id'],'claim'=>$claim,'payload'=>json_decode($job['payload'],true,64,JSON_THROW_ON_ERROR)]];
        }catch(Throwable $error){if($app->db->inTransaction())$app->db->rollBack();throw $error;}
    }
    $status=(string)($data['status']??'');if(!in_array($status,['sent_to_printer','pdf_created','uncertain','simulated'],true))throw new DomainException('Estado de impresión inválido.');
    $job=$app->one('SELECT * FROM fisitaap_print_jobs180 WHERE id=? AND tenant_id=? AND branch_id=? AND device_id=?',[(int)($data['id']??0),$device['tenant_id'],$device['branch_id'],$device['id']]);if(!$job||!hash_equals((string)$job['claim_token'],(string)($data['claim']??'')))throw new DomainException('La impresión no pertenece a este equipo o envío.');
    if($job['status']!=='claimed'){if($job['status']!==$status)throw new DomainException('La impresión ya tiene otro resultado.');return ['ok'=>true];}
    $app->exec('UPDATE fisitaap_print_jobs180 SET status=?,error=?,completed_at=NOW() WHERE id=? AND status="claimed" AND claim_token=?',[$status,mb_substr((string)($data['error']??''),0,500),$job['id'],$job['claim_token']]);return ['ok'=>true];
}
function qa180_printers(App $app,array $user,array $tenant):void {
    qa180_permission($app,$user,'impresion','configure');$branch=physical_branch_v14($app,$tenant);$points=r3_print_points($app,$tenant);$devices=$app->all('SELECT id,name,last_sync FROM fisitaap_r2_devices WHERE tenant_id=? AND branch_id=? AND is_active=1 AND token_hash IS NOT NULL ORDER BY name',[$tenant['id'],$branch['id']]);
    if(is_post()){
        verify_csrf();try{
            if(($_POST['action']??'')==='add_zone')r3_print_zone_save($app,$tenant);
            $profiles=[];foreach($points as $key=>$label){$p=(array)($_POST['printer_points'][$key]??[]);$type=(string)($p['type']??'browser');$width=(int)($p['width']??80);$device=(int)($p['device_id']??0);$host=trim((string)($p['host']??''));$port=(int)($p['port']??9100);$name=mb_substr(trim((string)($p['name']??'')),0,150);
                if(!in_array($type,['browser','usb','network'],true)||!in_array($width,[58,80],true)||$port<1||$port>65535)throw new DomainException('Revisa el tipo, papel y puerto de '.$label.'.');
                if($device&&!in_array($device,array_map('intval',array_column($devices,'id')),true))throw new DomainException('El equipo no pertenece a esta sucursal.');
                if($type==='usb'&&$name==='')throw new DomainException('Selecciona el nombre exacto de la impresora de Windows.');
                if($type==='network'&&(!filter_var($host,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4)||!preg_match('/^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/',$host)))throw new DomainException('Usa la IP privada de la impresora para '.$label.'.');
                $profiles[$key]=['type'=>$type,'width'=>$width,'device_id'=>$device,'host'=>$host,'port'=>$port,'name'=>$name,'autoprint'=>1,'drawer'=>$key==='receipt'&&!empty($p['drawer'])];
            }
            $app->exec('UPDATE branches SET printer_points_json=? WHERE id=? AND tenant_id=?',[json_encode($profiles,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$branch['id'],$tenant['id']]);
            qa180_audit($app,$user,'printer_config','branch',(int)$branch['id'],'Actualizó los destinos de impresión de '.$branch['name']);flash('success','Impresoras guardadas. Los envíos anteriores conservan su destino.');
        }catch(Throwable $error){flash('error',$error instanceof PDOException?'No se guardaron las impresoras.':$error->getMessage());}
        redirect(url('admin/impresion'));
    }
    admin_shell_start('Impresión',$user,$tenant,'impresion');echo '<section class="card admin-card"><h2>Impresoras de '.e($branch['name']).'</h2><p>La aplicación instalada envía los documentos directamente. Selecciona el equipo y la impresora de cada punto. PDF guarda un archivo sin pedir una impresora.</p><p data-native-status>Abre esta página en Windows o Android para comprobar el equipo.</p><button class="btn btn-light" type="button" data-printers-native>Buscar impresoras de este equipo</button><form method="post">'.csrf_field().'<div class="qa180-printer-grid">';
    foreach($points as $key=>$label){$p=printer_profile_148($branch,$key);$prefix='printer_points['.$key.']';echo '<fieldset class="card"><legend>'.e($label).'</legend><label>Equipo<select class="input" name="'.$prefix.'[device_id]"><option value="0">Equipo que origina la operación / principal de esta sucursal</option>';foreach($devices as $device)echo '<option value="'.$device['id'].'" '.($p['device_id']===(int)$device['id']?'selected':'').'>'.e($device['name']).'</option>';echo '</select></label><label>Conexión<select class="input" name="'.$prefix.'[type]">';foreach(['browser'=>'Guardar PDF','usb'=>'Impresora instalada en Windows','network'=>'Red · ESC/POS'] as $type=>$name)echo '<option value="'.$type.'" '.($p['type']===$type?'selected':'').'>'.e($name).'</option>';echo '</select></label><label>Papel<select class="input" name="'.$prefix.'[width]"><option value="58" '.($p['width']===58?'selected':'').'>58 mm</option><option value="80" '.($p['width']===80?'selected':'').'>80 mm</option></select></label><label>Nombre en Windows<input class="input" name="'.$prefix.'[name]" list="qa180NativePrinters" value="'.e($p['name']).'"></label><label>IP de la impresora<input class="input" name="'.$prefix.'[host]" value="'.e($p['host']).'" placeholder="192.168.1.50"></label><label>Puerto<input class="input" name="'.$prefix.'[port]" type="number" min="1" max="65535" value="'.$p['port'].'"></label>';if($key==='receipt')echo '<label><input type="checkbox" name="'.$prefix.'[drawer]" value="1" '.($p['drawer']?'checked':'').'> Abrir gaveta en recibos de efectivo. Activa también la gaveta en la caja de Equipos y cajas.</label>';echo '<button class="btn btn-light" type="button" data-print-test="'.e($key).'">Probar '.e($label).'</button></fieldset>';}
    echo '</div><datalist id="qa180NativePrinters"></datalist><button class="btn">Guardar impresoras</button></form><form method="post">'.csrf_field().pos_hidden_148('action','add_zone').field('Nueva zona de impresión','zone_name','',true).'<button class="btn btn-light">Agregar zona</button></form></section>';
    $jobs=$app->all('SELECT j.id,j.point,j.status,j.error,j.created_at,d.name device FROM fisitaap_print_jobs180 j LEFT JOIN fisitaap_r2_devices d ON d.id=j.device_id WHERE j.tenant_id=? AND j.branch_id=? ORDER BY j.id DESC LIMIT 50',[$tenant['id'],$branch['id']]);echo '<section class="card admin-card"><h2>Últimos envíos</h2><p>«Enviado» significa que Windows o la conexión de red aceptó los datos. Revisa papel y gaveta en el equipo real. Un envío sin confirmar requiere revisar la salida antes de hacer una copia.</p><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Punto</th><th>Equipo</th><th>Estado</th><th>Detalle</th></tr></thead><tbody>';foreach($jobs as $job)echo '<tr><td>'.e($job['created_at']).'</td><td>'.e($points[$job['point']]??$job['point']).'</td><td>'.e($job['device']??'Asignación pendiente').'</td><td>'.e(['queued'=>'En espera','claimed'=>'Enviando','sent_to_printer'=>'Enviado','pdf_created'=>'PDF guardado','uncertain'=>'Sin confirmar','simulated'=>'Demostración'][$job['status']]??$job['status']).'</td><td>'.e($job['error']??'').'</td></tr>';echo '</tbody></table></div></section>';admin_shell_end();
}
function qa180_print_test(App $app):never {
    [$user,$tenant]=qa180_business($app,'impresion');qa180_permission($app,$user,'impresion','configure');verify_csrf();$branch=physical_branch_v14($app,$tenant);$point=(string)($_POST['point']??'');
    try{$app->db->beginTransaction();$id=qa180_print_enqueue($app,$tenant,$branch,$user,$point,'test-'.bin2hex(random_bytes(12)),"PRUEBA DE IMPRESIÓN\n".$tenant['name']."\n".$branch['name']."\n".(r3_print_points($app,$tenant)[$point]??'')."\n58 / 80 mm · ₡ · áéíóú ñ\nSIN COBRO · SIN GAVETA",false);$app->db->commit();json_response(['ok'=>true,'id'=>$id]);}catch(Throwable $error){if($app->db->inTransaction())$app->db->rollBack();json_response(['ok'=>false,'error'=>$error instanceof PDOException?'No se pudo guardar la prueba.':$error->getMessage()],422);}
}
function qa180_gift_preview(App $app):never {
    [$user,$tenant]=qa180_business($app,'ventas');verify_csrf();
    try{qa180_permission($app,$user,'ventas','charge');qa180_native($app,$user,true);$customer=(int)($_POST['customer_id']??0);$code=strtoupper(trim((string)($_POST['code']??'')));if(!preg_match('/^[A-Z0-9-]{6,40}$/D',$code))throw new DomainException('Escribe el código de la tarjeta.');
        $card=$app->one('SELECT c.balance,c.customer_id FROM fisitaap_r3_gift_cards c JOIN tenant_customers tc ON tc.tenant_id=c.tenant_id AND tc.user_id=c.customer_id JOIN users u ON u.id=tc.user_id AND u.role="customer" AND u.is_active=1 WHERE c.tenant_id=? AND c.customer_id=? AND c.code=? AND c.status="active" AND c.expires_at>=NOW()',[$tenant['id'],$customer,$code]);if(!$card)throw new DomainException('La tarjeta no está disponible para este cliente.');json_response(['ok'=>true,'card'=>['customer_id'=>$customer,'code'=>$code,'balance'=>$card['balance']]]);
    }catch(Throwable $error){json_response(['ok'=>false,'error'=>$error instanceof PDOException?'No se pudo comprobar el saldo.':$error->getMessage()],403);}
}
